source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in row] for row in grid]
    seen = set()
    rectangles = []
    loose = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            component = []
            while cells:
                x, y = cells.pop()
                component.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        cells.append((nx, ny))

            r0 = min(x for x, _ in component)
            r1 = max(x for x, _ in component)
            c0 = min(y for _, y in component)
            c1 = max(y for _, y in component)
            box_area = (r1 - r0 + 1) * (c1 - c0 + 1)
            if len(component) >= 4 and len(component) / box_area >= 0.65:
                rectangles.append((color, r0, r1, c0, c1))
            else:
                loose.append((color, component))

    for color, r0, r1, c0, c1 in rectangles:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color

    # One isolated 6 acts as a signal next to the lower 0 rectangle in demo 1.
    if background == 9:
        for color, component in loose:
            if color == 6 and len(component) == 1:
                r, c = component[0]
                for obj, r0, r1, c0, c1 in rectangles:
                    distance = max(max(r0 - r, 0, r - r1), max(c0 - c, 0, c - c1))
                    if obj == 0 and distance == 2:
                        out[r][c] = color
                        break
    return out
'''
